pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address burnAddr, uint256 burnAmount) public {
        // Ensure burnAmount is not extremely large to avoid overflow in intermediate steps
        vm.assume(burnAmount <= c.totalDistributed());
        // First call XBornID() to set initial balances
        c.XBornID();
        // Get totalDistributed after the initial distribution
        uint256 distrAfterXBorn = c.totalDistributed();
        // Now burn from burnAddr (but we need to be owner to call burn); so we set the msg.sender to owner
        // We need to find the owner; but we can just use the default owner (deployer = this).
        // However burn may revert if burnAmount > balance of burnAddr; we assume burnAddr has at least that much in initial distribution
        // We can use the owner privilege to burn from any address? Actually burn only burns msg.sender's balance.
